package com.bank.kstream;

import java.util.PriorityQueue;
import java.util.logging.Logger;

// Maintains the Kth largest transaction amount over a live stream.
public class KthLargestStream {

    private static final Logger log = Logger.getLogger(KthLargestStream.class.getName());

    private final int k;
    private final PriorityQueue<Long> heap = new PriorityQueue<>(); // min-heap

    public KthLargestStream(int k, long[] seed) {
        this.k = k;
        for (long n : seed) {
            add(n); // reuse add so heap ends with K largest
        }
    }

    public long add(long amount) {
        heap.offer(amount);
        if (heap.size() > k) {
            heap.poll(); // drop smallest, keep K largest
        }
        long kth = heap.peek(); // root = Kth largest (or smallest so far if < K)
        log.info("Added " + amount + " -> Kth largest = " + kth);
        return kth;
    }
}
