package com.bank.kstream;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class KthStreamDemo {

    private static final Logger log = Logger.getLogger(KthStreamDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Kth Largest Transaction (Stream)");
        long[] seed = {4000, 5000, 8000, 2000};
        KthLargestStream k = new KthLargestStream(3, seed); // 3rd largest

        k.add(3000);  // stream continues
        k.add(10000);
        k.add(1000);
    }
}
